class Solution {
    private boolean balanced(int value){
        int[] count=new int[10];
        while(value>0){
            count[value%10]++;
            value/=10;
        }
        for(int digit=0;digit<10;digit++)if(count[digit]>0&&count[digit]!=digit)return false;
        return true;
    }
    public int nextBeautifulNumber(int n){
        for(int value=n+1;;value++)if(balanced(value))return value;
    }
}

code.kotlin:
class Solution {
    private fun balanced(valueValue:Int):Boolean{
        var value=valueValue;
        val count=IntArray(10);
        while(value>0){
            count[value%10]++;
            value/=10
        };
        return (0..9).all{
            count[it]==0||count[it]==it
        }
    };
    fun nextBeautifulNumber(n:Int):Int{
        var value=n+1;
        while(!balanced(value))value++;
        return value
    }
}

